import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Search, User, Menu, ArrowRight, Star, Globe, BookOpen } from 'lucide-react';
import api from '../services/api';

export default function Landing() {
  const navigate = useNavigate();
  const [scrolled, setScrolled] = useState(false);
  const [topProfs, setTopProfs] = useState([]);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    
    api.get('/api/professeurs/')
      .then(res => {
        const data = Array.isArray(res.data) ? res.data : [];
        const valid = data.filter(p => p.statut_validation === 'validé').slice(0, 4);
        setTopProfs(valid);
      })
      .catch(err => console.error("Erreur API:", err));

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const features = [
    { title: "Matching IA", desc: "Trouvez le mentor idéal.", Icon: Globe },
    { title: "Liberté totale", desc: "En ligne ou présentiel.", Icon: BookOpen },
    { title: "Excellence", desc: "Qualité académique garantie.", Icon: Star }
  ];

  return (
    <div className="min-h-screen bg-white text-[#1a1a1a]" style={{ fontFamily: '"Inter", sans-serif' }}>
      
      {/* --- NAVBAR --- */}
      <nav className={`fixed w-full z-50 transition-all duration-700 px-6 md:px-12 ${scrolled ? 'bg-white py-4 border-b border-gray-100' : 'bg-transparent py-8'}`}>
        <div className="max-w-[1800px] mx-auto flex justify-between items-center">
          <div className="flex items-center gap-12">
            <h1 className="text-xl font-light tracking-[0.3em] uppercase cursor-pointer" onClick={() => window.scrollTo(0,0)}>
              EduMatch
            </h1>
            <div className="hidden lg:flex gap-8 text-[10px] uppercase tracking-[0.2em] font-medium">
              <button onClick={() => navigate('/profs')} className="hover:opacity-50 transition">Formateurs</button>
              <button className="hover:opacity-50 transition">À propos</button>
            </div>
          </div>
          <div className="flex items-center gap-6">
            <Search size={18} strokeWidth={1.2} className="cursor-pointer hover:opacity-50 transition" />
            <div className="hidden md:flex gap-6 text-[10px] uppercase tracking-[0.2em]">
              <button onClick={() => navigate('/login')}>Connexion</button>
              <button onClick={() => navigate('/register')} className="font-bold">S'inscrire</button>
            </div>
            <Menu size={20} strokeWidth={1.2} className="lg:hidden cursor-pointer" />
          </div>
        </div>
      </nav>

      {/* --- HERO SECTION --- */}
      <section className="relative h-screen flex items-center justify-center overflow-hidden bg-[#f9f9f9]">
        <div className="relative z-10 text-center px-4">
          <motion.span 
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 1 }}
            className="text-[10px] uppercase tracking-[0.5em] text-gray-400 mb-8 block"
          >
            L'excellence académique
          </motion.span>
          <motion.h2 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1, delay: 0.3 }}
            className="text-5xl md:text-8xl font-extralight tracking-tighter leading-none mb-12"
          >
            Apprenez sans <br />
            <span className="italic font-serif">compromis.</span>
          </motion.h2>
          <form 
            onSubmit={(e) => { e.preventDefault(); navigate(`/profs?q=${search}`); }}
            className="flex max-w-xl mx-auto border-b border-black py-2"
          >
            <input 
              type="text" 
              placeholder="Rechercher une matière..." 
              className="bg-transparent w-full text-sm uppercase tracking-widest outline-none"
              onChange={(e) => setSearch(e.target.value)}
            />
            <button type="submit"><ArrowRight size={20} strokeWidth={1} /></button>
          </form>
        </div>
      </section>

      {/* --- MENTORS SECTION --- */}
      <section className="py-32 px-6 md:px-12 max-w-[1600px] mx-auto text-center md:text-left">
        <div className="flex justify-between items-end mb-16 border-b border-gray-100 pb-8">
          <h2 className="text-2xl font-light uppercase tracking-widest">Nos Mentors</h2>
          <button onClick={() => navigate('/profs')} className="text-[10px] uppercase tracking-widest border-b border-black pb-1">Voir tout</button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
          {topProfs.length > 0 ? topProfs.map((p, i) => (
            <div key={i} className="group cursor-pointer" onClick={() => navigate('/login')}>
              <div className="aspect-[3/4] bg-[#f5f5f5] mb-6 overflow-hidden">
                <img 
                  src={p.photo_url ? `http://localhost:8001${p.photo_url}` : "https://via.placeholder.com/600x800?text=Mentor"} 
                  className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-[1s]" 
                  alt={p.user_nom} 
                />
              </div>
              <h4 className="text-[11px] uppercase tracking-widest font-medium">{p.user_prenom} {p.user_nom}</h4>
              <p className="text-[10px] text-gray-400 uppercase mt-1 italic tracking-widest">{p.tarifs_matieres?.[0]?.nom_matiere || 'Enseignant'}</p>
            </div>
          )) : <p className="text-xs uppercase tracking-widest text-gray-300">Chargement des mentors...</p>}
        </div>
      </section>

      {/* --- FEATURES SECTION --- */}
      <section className="bg-[#fcfcfc] py-32 border-y border-gray-50">
        <div className="max-w-[1400px] mx-auto grid grid-cols-1 md:grid-cols-3 gap-24 px-6">
          {features.map((f, i) => (
            <div key={i} className="text-center flex flex-col items-center">
              <div className="mb-8 text-gray-300">
                <f.Icon size={32} strokeWidth={1} />
              </div>
              <h3 className="text-[11px] uppercase tracking-[0.3em] font-bold mb-4">{f.title}</h3>
              <p className="text-[10px] text-gray-400 leading-relaxed uppercase tracking-widest font-light max-w-[200px]">
                {f.desc}
              </p>
            </div>
          ))}
        </div>
      </section>

      {/* --- FOOTER --- */}
      <footer className="py-24 px-6 md:px-12 bg-white border-t border-gray-100">
        <div className="max-w-[1600px] mx-auto grid grid-cols-1 md:grid-cols-4 gap-16">
          <div className="col-span-1 md:col-span-2">
            <h2 className="text-sm tracking-[0.4em] uppercase mb-8">EduMatch</h2>
            <p className="text-[10px] text-gray-400 leading-relaxed uppercase tracking-widest italic max-w-xs">
              Une nouvelle vision de l'éducation, alliant élégance et performance technologique.
            </p>
          </div>
          <div>
            <span className="text-[9px] uppercase tracking-[0.3em] font-bold text-gray-300 mb-6 block">Assistance</span>
            <ul className="text-[10px] uppercase tracking-widest flex flex-col gap-4">
              <li className="cursor-pointer hover:opacity-50">Contact</li>
              <li className="cursor-pointer hover:opacity-50">FAQ</li>
            </ul>
          </div>
          <div>
            <span className="text-[9px] uppercase tracking-[0.3em] font-bold text-gray-300 mb-6 block">Newsletter</span>
            <div className="flex border-b border-black pb-2">
              <input type="text" placeholder="VOTRE EMAIL" className="text-[10px] w-full bg-transparent outline-none tracking-widest" />
              <button className="text-[10px] font-bold tracking-widest hover:opacity-50">OK</button>
            </div>
          </div>
        </div>
        <div className="max-w-[1600px] mx-auto mt-24 text-[8px] uppercase tracking-[0.4em] text-gray-300">
          © {new Date().getFullYear()} EDUMATCH TUNISIA - PROJET PFE
        </div>
      </footer>

    </div>
  );
}
